package org.springframework.samples.petclinic.rest.function.owner;

import java.time.LocalDate;

import org.springframework.samples.petclinic.model.Owner;

/**
 * Membership scoring. Points start at 0 and add: +2 when an email is present, +1 when the owner
 * has no namesakes (namesakeCount 0), +2 for a household of 3 or more, +3 for tenure over 365 days.
 * Points map to a level: 1 (0-1 points), 2 (2-3), 3 (4-5), 4 (6 or more).
 */
public final class MembershipPoints {

    private MembershipPoints() {
    }

    public static int of(Owner owner) {
        int points = 0;
        if (owner.getEmail() != null && !owner.getEmail().isBlank()) {
            points += 2;
        }
        if (Integer.valueOf(0).equals(owner.getNamesakeCount())) {
            points += 1;
        }
        if (owner.getHouseholdCount() != null && owner.getHouseholdCount() >= 3) {
            points += 2;
        }
        LocalDate registration = owner.getRegistrationDate();
        if (registration != null && FiscalYear.elapsedTo(registration, LocalDate.now()) >= 1) {
            points += 3;
        }
        return points;
    }

    public static int level(int points) {
        if (points <= 1) {
            return 1;
        }
        if (points <= 3) {
            return 2;
        }
        if (points <= 5) {
            return 3;
        }
        return 4;
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Records how many owners belong to this owner's household (same computed {@code householdId} —
 * last name and postcode, see {@link HouseholdId}) after this create, i.e. the existing members
 * plus the new owner. Drives the 'GOLD' membership tier.
 */
public class CountHousehold {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        String household = HouseholdId.of(owner.getLastName(), owner.getPostcode());
        long existing = ownerRepository.findAll().stream()
                .filter(other -> household.equals(HouseholdId.of(other.getLastName(), other.getPostcode())))
                .count();
        owner.setHouseholdCount((int) existing + 1);
    }
}
package org.springframework.samples.petclinic.rest.function.owner;

import java.nio.charset.StandardCharsets;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.HexFormat;

/**
 * Deterministic household identifier: the first 12 hex characters of SHA-256 over
 * {@code normalizedLastName + '|' + postcode}. Owners with the same last name and postcode share it,
 * so it keys household duplicate detection and the household-size count.
 */
public final class HouseholdId {

    private HouseholdId() {
    }

    public static String of(String lastName, String postcode) {
        String key = normalize(lastName) + "|" + (postcode == null ? "" : postcode);
        try {
            byte[] digest = MessageDigest.getInstance("SHA-256").digest(key.getBytes(StandardCharsets.UTF_8));
            return HexFormat.of().formatHex(digest).substring(0, 12);
        }
        catch (NoSuchAlgorithmException ex) {
            throw new IllegalStateException(ex);
        }
    }

    private static String normalize(String value) {
        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase();
    }
}

